public sealed record UiMainResult(ApiCurrentSnapshot? Current, ApiAccountsSnapshot? Choices, DetailsFetchFailure? Failure);
public interface ILoopbackUiClient : IUiChangeClient
{
    Task<UiMainResult> FetchMainAsync(string? accountId, bool includeChoices, CancellationToken cancellationToken = default);
    Task<ApiAccount?> FetchAccountContextAsync(string accountId, CancellationToken cancellationToken = default);
    Task CheckAsync(CancellationToken cancellationToken = default);
    bool AccountChoicesVisible { get; }
    void SetViewVisible(string view, bool visible);
    Task<HistoryPeriodsFetchResult> FetchWindowPeriodsAsync(string accountId, long from, long until, CancellationToken cancellationToken = default);
}
/// <summary>One versionless UI client; all screens share this transport and receiver.</summary>
public sealed class LoopbackStatusClient : ILoopbackHealthClient, ILoopbackRuntimeVersionsClient, ILoopbackDetailsClient, ILoopbackResourceClient, ILoopbackAccountsClient, ILoopbackAccountResourceClient, ILoopbackUiClient, IDisposable
{
    readonly HashSet<string> visibleViews = new(StringComparer.Ordinal); readonly object visibilityGate = new();
    readonly WireTransport wire; readonly string? ownedTestCache; string? selectedAccount; readonly object drainGate = new(); readonly Dictionary<string, (Task Task, CancellationTokenSource Cancel)> drains = new(StringComparer.Ordinal); readonly CancellationTokenSource lifetime = new(); readonly ConcurrentDictionary<string, Exception> drainFailures = new(StringComparer.Ordinal); readonly ConcurrentDictionary<string, ApiAccount> contexts = new(StringComparer.Ordinal);
    public LoopbackStatusClient() : this(WireTransport.DefaultHandler(), ResolveEndpoint(), ResolveCache(), false) { }
    public LoopbackStatusClient(HttpMessageHandler handler) : this(handler, ResolveEndpoint(), Path.Combine(Path.GetTempPath(), "codex-info-wire-test-" + Guid.NewGuid().ToString("N")), true) { }
    public LoopbackStatusClient(HttpMessageHandler handler, Uri endpoint, string cacheDirectory) : this(handler, endpoint, cacheDirectory, false) { }
    LoopbackStatusClient(HttpMessageHandler handler, Uri endpoint, string cacheDirectory, bool owned) { wire = new(handler, endpoint, cacheDirectory); _ = wire.SetUiScopesAsync(false, false, false); if (owned) ownedTestCache = cacheDirectory; }
    static Uri ResolveEndpoint() { var raw = Environment.GetEnvironmentVariable("CODEX_INFO_WINDOWS_E2E_FIXTURE_PORT"); if (raw is null) return new("http://127.0.0.1:8787/"); if (!ushort.TryParse(raw, out var port) || port == 0) throw new InvalidOperationException("invalid fixture port"); return new($"http://127.0.0.1:{port}/"); }
    static string ResolveCache() { var settings = Environment.GetEnvironmentVariable("CODEX_INFO_WINDOWS_E2E_SETTINGS_PATH"); var root = settings is null ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "CodexInfo") : Path.GetDirectoryName(Path.GetFullPath(settings))!; return Path.Combine(root, "wire-receipts"); }
    public bool AccountChoicesVisible { get { lock (visibilityGate) return visibleViews.Contains("settings"); } }
    public void SetViewVisible(string view, bool visible) { if (view is not ("settings" or "graph" or "threads")) throw new ArgumentException("invalid UI scope"); bool settings, graph, threads; lock (visibilityGate) { if (visible ? !visibleViews.Add(view) : !visibleViews.Remove(view)) return; settings = visibleViews.Contains("settings"); graph = visibleViews.Contains("graph"); threads = visibleViews.Contains("threads"); } if (!visible) { lock (drainGate) foreach (var (target, drain) in drains) if (view == "graph" && target.StartsWith("/history", StringComparison.Ordinal) || view == "threads" && target.StartsWith("/threads", StringComparison.Ordinal) || view == "settings" && target.Contains("account_choices", StringComparison.Ordinal)) drain.Cancel.Cancel(); } _ = ChangeScopesAsync(settings, graph, threads); }
    async Task ChangeScopesAsync(bool settings, bool graph, bool threads) { try { await wire.SetUiScopesAsync(settings, graph, threads, lifetime.Token).ConfigureAwait(false); } catch (OperationCanceledException) when (lifetime.IsCancellationRequested) { } catch (Exception) { } finally { wire.Wake(); } }
    public long ChangeRevision => wire.ChangeRevision;
    public Task<long> WaitForChangeAsync(long after, CancellationToken token) => wire.WaitForChangeAsync(after, token);
    public Task CheckAsync(CancellationToken token = default) => wire.CheckAsync(token);
    static string Account(string id) => Safe(id) ? id : throw new ArgumentException("invalid account selector");
    static bool Safe(string value) => value.Length is > 0 and <= 1024 && value.All(ch => char.IsAsciiLetterOrDigit(ch) || ch is '-' or '_' or '.' or '~');
    static string Scope(string? id) => id is null ? "" : "&account=" + Account(id);
    static DetailsFetchFailure Failure(Exception error) => error switch { WirePendingException => DetailsFetchFailure.Pending, WireCacheRecoveryException => DetailsFetchFailure.CacheRecovery, WireHttpException => DetailsFetchFailure.Response, InvalidDataException => DetailsFetchFailure.Response, OperationCanceledException => DetailsFetchFailure.Transport, HttpRequestException => DetailsFetchFailure.Transport, IOException => DetailsFetchFailure.Transport, _ => DetailsFetchFailure.Response };
    static WireRow Row(WirePage page, string kind) => page.Views.SelectMany(view => view.Rows).Single(row => row.Key[0].GetString() == kind);
    static WireViewSnapshot View(WirePage page, string kind) => page.Views.Single(view => view.Rows.Any(row => row.Key[0].GetString() == kind));
    static PublishedPairIdentity Image(string image) => PublishedPairIdentity.Create(image);
    static long? Time(JsonElement value, string key) => value.TryGetProperty(key, out var field) && field.ValueKind != JsonValueKind.Null ? field.GetInt64() : null;
    static ulong? Count(JsonElement value, string key) => value.TryGetProperty(key, out var field) && field.ValueKind != JsonValueKind.Null ? field.GetUInt64() : null;
    static string? Text(JsonElement value, string key) => value.TryGetProperty(key, out var field) && field.ValueKind != JsonValueKind.Null ? field.GetString() : null;
    static double? Money(JsonElement value, string key) => value.TryGetProperty(key, out var field) && field.ValueKind != JsonValueKind.Null ? field.GetDouble() : null;
    static ApiState State(string value) => value switch { "initializing" => ApiState.Initializing, "ready" => ApiState.Ready, "auth_required" => ApiState.AuthRequired, "error" => ApiState.Error, _ => throw new InvalidDataException("invalid acquisition state") };
    static ApiCurrentModelsStatus ModelsStatus(string value) => value switch { "complete" => ApiCurrentModelsStatus.Complete, "partial" => ApiCurrentModelsStatus.Partial, "unavailable" => ApiCurrentModelsStatus.Unavailable, _ => throw new InvalidDataException("invalid models status") };
    public async Task<UiMainResult> FetchMainAsync(string? accountId, bool includeChoices, CancellationToken token = default)
    {
        try { var page = await CompleteAsync("/state?parts=" + (includeChoices ? "main,account_choices" : "main") + Scope(accountId), token).ConfigureAwait(false); if (!page.Views.SelectMany(v => v.Rows).Any(row => row.Key[0].GetString() == "main")) throw new WirePendingException("preparing"); var current = ParseCurrent(Row(page, "main").Value, Image(View(page, "main").Image)); selectedAccount = current.AccountId; return new(current, includeChoices ? ParseChoices(Row(page, "account_choices").Value) : null, null); } catch (Exception error) when (error is not OperationCanceledException || !token.IsCancellationRequested) { return new(null, null, Failure(error)); }
    }
    async Task<WirePage> CompleteAsync(string target, CancellationToken token)
    {
        if (drainFailures.TryRemove(target, out var failure)) throw failure;
        lock (drainGate) if (drains.TryGetValue(target, out var active) && !active.Task.IsCompleted) throw new WirePendingException("preparing");
        var page = await wire.GetAsync(target, token).ConfigureAwait(false);
        if (page.Delivery is JsonElement data && Text(data, "next_cursor") is string cursor) { lock (drainGate) { if (!drains.TryGetValue(target, out var active) || active.Task.IsCompleted) { var cancel = CancellationTokenSource.CreateLinkedTokenSource(lifetime.Token); drains[target] = (Task.Run(() => DrainAsync(target, cursor, cancel)), cancel); } } throw new WirePendingException("preparing"); }
        return page;
    }
    async Task DrainAsync(string target, string cursor, CancellationTokenSource cancel)
    {
        try { var seen = new HashSet<string>(StringComparer.Ordinal); while (true) { var revision = wire.ChangeRevision; WirePage page; try { page = await wire.GetAsync(target + "&cursor=" + cursor, cancel.Token).ConfigureAwait(false); } catch (WirePendingException error) when (error.Reason != "cursor_outdated") { await wire.WaitForChangeAsync(revision, cancel.Token).ConfigureAwait(false); continue; } if (!seen.Add(cursor)) throw new InvalidDataException("repeated cursor"); if (page.Delivery is not JsonElement data || Text(data, "next_cursor") is not string next) break; cursor = next; } }
        catch (OperationCanceledException) when (cancel.IsCancellationRequested) { }
        catch (WirePendingException) { }
        catch (Exception error) { drainFailures[target] = error; }
        finally { lock (drainGate) drains.Remove(target); cancel.Dispose(); wire.Wake(); }
    }
    static ApiCurrentSnapshot ParseCurrent(JsonElement value, PublishedPairIdentity image)
    {
        var quota = value.GetProperty("quota"); var selection = value.GetProperty("selection"); var summary = value.GetProperty("thread_summary");
        var threadSummary = summary.ValueKind == JsonValueKind.Null ? null : new ApiThreadSummary(summary.GetProperty("open_count").GetUInt64(), summary.GetProperty("running_count").GetUInt64(), summary.GetProperty("unknown_activity_count").GetUInt64(), summary.GetProperty("by_model").EnumerateArray().Select(row => new ApiThreadModelCount(Text(row, "model"), row.GetProperty("open_count").GetUInt64(), row.GetProperty("running_count").GetUInt64(), row.GetProperty("unknown_activity_count").GetUInt64())).ToArray());
        if (threadSummary is not null && (threadSummary.ByModel.Aggregate(0ul, (sum, row) => checked(sum + row.OpenCount)) != threadSummary.OpenCount || threadSummary.RunningCount > threadSummary.OpenCount || threadSummary.UnknownActivityCount > threadSummary.OpenCount - threadSummary.RunningCount)) throw new InvalidDataException("thread summary mismatch");
        var models = value.GetProperty("models").EnumerateArray().Select(ParseModel).ToArray(); var state = State(value.GetProperty("acquisition_state").GetString()!); var authenticated = value.GetProperty("authenticated").GetBoolean(); var observed = Time(value, "observed_at"); if (state == ApiState.Ready && (!authenticated || observed is null)) throw new InvalidDataException("incomplete ready state");
        return new(state, observed, authenticated, Text(value, "plan_label"), quota.ValueKind == JsonValueKind.Null ? null : new ApiQuota(quota.GetProperty("remaining_percent").GetDouble(), quota.GetProperty("reset_at").GetInt64(), quota.GetProperty("window_seconds").GetInt64(), quota.GetProperty("monthly").GetBoolean()), models, threadSummary?.RunningCount ?? 0, image) { ModelsStatus = ModelsStatus(value.GetProperty("models_status").GetString()!), OpenSessionThreadCount = threadSummary?.OpenCount ?? 0, ThreadSummary = threadSummary, AccountId = selection.ValueKind == JsonValueKind.Null ? null : selection.GetProperty("account_id").GetString(), Selection = selection.ValueKind == JsonValueKind.Null ? null : new ApiAccount(selection.GetProperty("account_id").GetString()!, selection.GetProperty("is_current").GetBoolean(), null, null, Text(selection, "login_id")) };
    }
    static ApiDetailsModelUsage ParseModel(JsonElement value)
    {
        var input = value.GetProperty("input_tokens").GetUInt64(); var cached = value.GetProperty("cached_input_tokens").GetUInt64(); var output = value.GetProperty("output_tokens").GetUInt64(); var total = value.GetProperty("total_tokens").GetUInt64(); var write = Count(value, "cache_write_input_tokens"); if (cached > input || write > input - cached || input > total || output != total - input) throw new InvalidDataException("invalid model tokens");
        var cost = value.GetProperty("estimated_cost"); var known = cost.ValueKind != JsonValueKind.Null; var ordinary = known ? cost.GetProperty("ordinary_input_dollars").GetDouble() : double.NaN; var writeCost = known ? cost.GetProperty("cache_write_input_dollars").GetDouble() : double.NaN;
        return new(value.GetProperty("model").GetString()!, input - cached, cached, output, ordinary + writeCost, known ? cost.GetProperty("cached_input_dollars").GetDouble() : double.NaN, known ? cost.GetProperty("output_dollars").GetDouble() : double.NaN) { TotalTokens = total, CacheWriteInputTokens = write, CacheWriteInputDollars = writeCost, PriceVersion = known ? cost.GetProperty("price_revision").GetString() : null, EstimatedTotalDollars = known ? cost.GetProperty("total_dollars").GetDouble() : null };
    }
    ApiAccountsSnapshot ParseChoices(JsonElement value) => new(Text(value, "default_account_id"), value.GetProperty("accounts").EnumerateArray().Select(account => { var id = account.GetProperty("id").GetString()!; contexts.TryGetValue(id, out var context); return new ApiAccount(id, account.GetProperty("is_current").GetBoolean(), context?.ActivationAt, context?.DeactivationAt, Text(account, "login_id")) { OwnershipIntervals = context?.OwnershipIntervals }; }).ToArray());
    public async Task<ApiAccount?> FetchAccountContextAsync(string accountId, CancellationToken token = default) { var page = await CompleteAsync("/state?parts=account_context&account=" + Account(accountId), token).ConfigureAwait(false); var value = Row(page, "account_context").Value; var intervals = value.GetProperty("ownership_intervals").EnumerateArray().Select(interval => new ApiAccountOwnershipInterval(Time(interval, "start_at"), Time(interval, "end_at"))).ToArray(); var result = new ApiAccount(accountId, false, Time(value, "activation_at"), Time(value, "deactivation_at")) { OwnershipIntervals = intervals.Length == 0 ? null : intervals }; contexts[accountId] = result; return result; }
    public async Task<CurrentFetchResult> FetchCurrentAsync(CancellationToken cancellationToken = default) { var result = await FetchMainAsync(selectedAccount, false, cancellationToken).ConfigureAwait(false); return result.Current is null ? CurrentFetchResult.FromFailure(result.Failure ?? DetailsFetchFailure.Pending) : CurrentFetchResult.Success(result.Current); }
    public async Task<CurrentFetchResult> FetchCurrentAsync(string accountId, CancellationToken cancellationToken = default) { var result = await FetchMainAsync(accountId, false, cancellationToken).ConfigureAwait(false); return result.Current is null ? CurrentFetchResult.FromFailure(result.Failure ?? DetailsFetchFailure.Pending) : CurrentFetchResult.Success(result.Current); }
    public async Task<AccountsFetchResult> FetchAccountsAsync(CancellationToken cancellationToken = default) { try { var page = await CompleteAsync("/state?parts=account_choices", cancellationToken).ConfigureAwait(false); return AccountsFetchResult.Success(ParseChoices(Row(page, "account_choices").Value)); } catch (Exception error) { return AccountsFetchResult.FromFailure(Failure(error)); } }
    public async Task<RuntimeVersionsFetchResult> FetchRuntimeVersionsAsync(CancellationToken cancellationToken = default) { try { var page = await CompleteAsync("/state?parts=runtime", cancellationToken).ConfigureAwait(false); var value = Row(page, "runtime").Value; return new(new ApiRuntimeVersionsSnapshot("", value.GetProperty("rest_product_version").GetString()!, Text(value, "recorder_product_version"), value.GetProperty("recorder_status").GetString()!), null); } catch (Exception error) { return new(null, Failure(error) == DetailsFetchFailure.Transport ? HealthFetchFailure.Transport : HealthFetchFailure.Response); } }
    public async Task<HealthFetchResult> FetchHealthAsync(CancellationToken cancellationToken = default) { var result = await FetchMainAsync(selectedAccount, false, cancellationToken).ConfigureAwait(false); return result.Current is not null || result.Failure == DetailsFetchFailure.Pending ? HealthFetchResult.Success(new ApiHealthSnapshot("", "codex-info", "")) : HealthFetchResult.FromFailure(result.Failure == DetailsFetchFailure.Transport ? HealthFetchFailure.Transport : HealthFetchFailure.Response); }
    public async Task<DetailsFetchResult> FetchDetailsAsync(CancellationToken cancellationToken = default) { var current = await FetchCurrentAsync(cancellationToken).ConfigureAwait(false); if (current.Snapshot is not { } value) return DetailsFetchResult.FromFailure(current.Failure ?? DetailsFetchFailure.Pending); return DetailsFetchResult.Success(new ApiDetailsSnapshot(value.State, value.ObservedAt, value.Authenticated, value.PlanLabel, value.Quota, value.Models, value.ActiveThreadCount, [], [], [], "未取得") { OpenSessionThreadCount = value.OpenSessionThreadCount, ModelsStatus = value.ModelsStatus, PublishedPair = value.PublishedPair, AccountId = value.AccountId, ThreadSummary = value.ThreadSummary, UseStoredPrices = true }); }
    public Task<HistoryPeriodsFetchResult> FetchHistoryPeriodsAsync(CancellationToken cancellationToken = default) => Periods(selectedAccount, true, cancellationToken);
    public Task<HistoryPeriodsFetchResult> FetchHistoryPeriodsAsync(string accountId, CancellationToken cancellationToken = default) => Periods(accountId, true, cancellationToken);
    public Task<HistoryPeriodsFetchResult> FetchSelectableHistoryPeriodsAsync(CancellationToken cancellationToken = default) => Periods(selectedAccount, true, cancellationToken);
    public Task<HistoryPeriodsFetchResult> FetchSelectableHistoryPeriodsAsync(string accountId, CancellationToken cancellationToken = default) => Periods(accountId, true, cancellationToken);
    public Task<HistoryPeriodsFetchResult> FetchWindowPeriodsAsync(string accountId, long from, long until, CancellationToken token = default) { if (from <= 0 || until <= from || until > 253402300800) throw new ArgumentException("invalid display bounds"); return Periods(accountId, false, token, from, until); }
    async Task<HistoryPeriodsFetchResult> Periods(string? account, bool selectable, CancellationToken token, long? from = null, long? until = null)
    {
        if (account is null) return HistoryPeriodsFetchResult.FromFailure(DetailsFetchFailure.Pending);
        try { var target = "/history/periods?account=" + Account(account) + "&purpose=" + (selectable ? "selectable" : "window&from=" + from!.Value.ToString(System.Globalization.CultureInfo.InvariantCulture) + "&until=" + until!.Value.ToString(System.Globalization.CultureInfo.InvariantCulture)); var page = await CompleteAsync(target, token).ConfigureAwait(false); var periods = page.Views.SelectMany(view => view.Rows).Where(row => row.Key[0].GetString() == "period").Select(row => { var value = row.Value; return new ApiHistoryPeriod(value.GetProperty("id").GetString()!, value.GetProperty("start_at").GetInt64(), value.GetProperty("end_at").GetInt64(), value.GetProperty("current").GetBoolean(), value.GetProperty("label").GetString()!) { ResetAt = value.GetProperty("reset_at").GetInt64(), OriginAt = Time(value, "origin_at") }; }).OrderByDescending(period => period.ResetAt).ThenBy(period => period.Id, StringComparer.Ordinal).ToArray(); return HistoryPeriodsFetchResult.Success(new(periods, Image(page.Views.Single().Image)) { AccountId = account }); } catch (Exception error) { return HistoryPeriodsFetchResult.FromFailure(Failure(error)); }
    }
    public Task<HistoryPageFetchResult> FetchHistoryPageAsync(string periodId, string? cursor = null, CancellationToken cancellationToken = default) => History(selectedAccount, periodId, cursor, cancellationToken);
    public Task<HistoryPageFetchResult> FetchHistoryPageAsync(string accountId, string periodId, string? cursor = null, CancellationToken cancellationToken = default) => History(accountId, periodId, cursor, cancellationToken);
    async Task<HistoryPageFetchResult> History(string? account, string period, string? cursor, CancellationToken token)
    {
        if (account is null) return HistoryPageFetchResult.FromFailure(DetailsFetchFailure.Pending);
        try
        {
            if (!Safe(period) || cursor is not null && !Safe(cursor)) throw new ArgumentException("invalid history selector"); var page = await CompleteAsync("/history?account=" + Account(account) + "&period=" + period + (cursor is null ? "" : "&cursor=" + cursor), token).ConfigureAwait(false); var rows = page.Views.SelectMany(v => v.Rows).ToArray(); var image = page.Views.FirstOrDefault()?.Image;

            var samples = rows.Where(row => row.Key[0].GetString() == "sample").Select(row => { var value = row.Value; var models = value.GetProperty("models"); return new ApiHistorySample(row.Key[3].GetInt64(), row.Key[2].GetInt64(), Money(value, "remaining_percent"), null, null, null, null, null, null, value.GetProperty("model_source").GetString()!) { ModelsComplete = value.GetProperty("models_complete").GetBoolean(), TaskActiveSincePrevious = value.GetProperty("task_active_since_previous").ValueKind == JsonValueKind.Null ? null : value.GetProperty("task_active_since_previous").GetBoolean(), ModelSamples = models.ValueKind == JsonValueKind.Null ? null : models.EnumerateArray().Select(model => new ApiHistoryModelSample(model.GetProperty("model").GetString()!, Count(model, "input_tokens"), Count(model, "cached_input_tokens"), Count(model, "output_tokens"), Money(model, "total_dollars")) { TotalTokens = model.GetProperty("total_tokens").GetUInt64(), CacheWriteInputTokens = Count(model, "cache_write_input_tokens") }).ToArray() }; }).ToArray();
            var gaps = rows.Where(row => row.Key[0].GetString() == "gap").Select(row => new ApiHistoryGap(row.Key[2].GetString()!, row.Value.GetProperty("reset_at").GetInt64(), row.Value.GetProperty("start_at").GetInt64(), row.Value.GetProperty("end_at").GetInt64(), row.Value.GetProperty("reason").GetString()!)).ToArray();
            var local = rows.FirstOrDefault(row => row.Key[0].GetString() == "local_usage")?.Value; ApiLocalUsage? usage = local is JsonElement e ? new(e.GetProperty("start_at").GetInt64(), e.GetProperty("end_at").GetInt64(), e.GetProperty("intervals").EnumerateArray().Select(i => new ApiLocalUsageInterval(i.GetProperty("start_at").GetInt64(), i.GetProperty("end_at").GetInt64(), i.GetProperty("state").GetString()!)).ToArray()) : null;
            return HistoryPageFetchResult.Success(new(period, samples, gaps, page.Delivery is JsonElement d ? Text(d, "next_cursor") : null, null, Image(image ?? throw new WirePendingException("preparing"))) { AccountId = account, LocalUsage = usage });
        }
        catch (WirePendingException error) when (error.Reason == "cursor_outdated") { return HistoryPageFetchResult.FromRejectedCursor(); }
        catch (Exception error) { return HistoryPageFetchResult.FromFailure(Failure(error)); }
    }
    public Task<ThreadsFetchResult> FetchThreadsAsync(CancellationToken cancellationToken = default) => Threads(selectedAccount, cancellationToken);
    public Task<ThreadsFetchResult> FetchThreadsAsync(string accountId, CancellationToken cancellationToken = default) => Threads(accountId, cancellationToken);
    async Task<ThreadsFetchResult> Threads(string? account, CancellationToken token) { if (account is null) return ThreadsFetchResult.FromFailure(DetailsFetchFailure.Pending); try { var page = await CompleteAsync("/threads?account=" + Account(account), token).ConfigureAwait(false); if (page.Views.Count != 1) throw new WirePendingException("preparing"); var rows = page.Views[0].Rows.Where(row => row.Key[0].GetString() == "thread").Select(row => { var value = row.Value; return new ApiThreadDetails(row.Key[1].GetString()!, value.GetProperty("title").GetString()!, Text(value, "parent_thread_id"), Text(value, "model") ?? "", value.GetProperty("model_label").GetString()!, Count(value, "total_tokens"), Count(value, "context_usage_tokens"), Count(value, "context_window_tokens"), Time(value, "created_at"), Time(value, "last_user_message_at"), value.GetProperty("is_subagent").GetBoolean(), Time(value, "depth") is long depth ? checked((int)depth) : null, false) { ActivityStatus = value.GetProperty("activity_status").GetString() switch { "running" => ApiThreadActivityStatus.Running, "stopped" => ApiThreadActivityStatus.Stopped, "unknown" => ApiThreadActivityStatus.Unknown, _ => throw new InvalidDataException("invalid activity state") } }; }).ToArray(); var ids = rows.Select(row => row.Id).ToHashSet(StringComparer.Ordinal); rows = rows.Select(row => row with { IsOrphan = row.ParentId is not null && !ids.Contains(row.ParentId) }).ToArray(); return ThreadsFetchResult.Success(new(rows, Image(page.Views[0].Image)) { AccountId = account }); } catch (Exception error) { return ThreadsFetchResult.FromFailure(Failure(error)); } }
    int disposed;
    public void Dispose() { if (Interlocked.Exchange(ref disposed, 1) != 0) return; lifetime.Cancel(); wire.Dispose(); lifetime.Dispose(); if (ownedTestCache is not null) { foreach (var path in Directory.EnumerateFiles(ownedTestCache)) File.Delete(path); Directory.Delete(ownedTestCache); File.Delete(Path.ChangeExtension(ownedTestCache, "identity")); } }
